const AIM={kcal:'kcal',prot:'prot',carb:'carb',sug:'acucar',fat:'gord',sat:'sat',trans:'trans',fib:'fibra',na:'sodio_mg',ca:'calcio_mg',fe:'ferro_mg',k:'potassio_mg',chol:'colest_mg',vC:'vitc_mg',mg:'magnesio_mg',zn:'zinco_mg',p:'fosforo_mg',vA:'vita_ug',vD:'vitd_ug',vE:'vite_mg',vK:'vitk_ug',vB12:'vitb12_ug',fol:'folato_ug',b1:'b1_mg',b2:'b2_mg',b3:'b3_mg',b5:'b5_mg',b6:'b6_mg',cu:'cobre_mg',mn:'manganes_mg',se:'selenio_ug',i:'iodo_ug',cho:'colina_mg'};
