const aiGet=()=>{try{return JSON.parse(localStorage.getItem(AIK))||{}}catch(e){return{}}};
const aiKeys=a=>((a.keys&&a.keys.length?a.keys:[a.key])||[]).filter(Boolean);
const aiOn=()=>{const a=aiGet();return!!(aiKeys(a).length&&a.url&&a.model)};
function aiSeed(){try{if(localStorage.getItem('jd_ai_seeded'))return;const a=JSON.parse(localStorage.getItem(AIK)||'null');
if(!a||!aiKeys(a).length)localStorage.setItem(AIK,JSON.stringify(Object.assign({},a||{},{url:(a&&a.url)||'https://openrouter.ai/api/v1',model:(a&&a.model)||'openrouter/free',key:AI_KEYS[0],keys:AI_KEYS.slice(),auto:a&&a.auto===false?false:true})));
else{a.keys=aiKeys(a).concat(AI_KEYS).filter((k,i,l)=>l.indexOf(k)==i);localStorage.setItem(AIK,JSON.stringify(a))}
localStorage.setItem('jd_ai_seeded','1')}catch(e){}}
aiSeed();
const jx=t=>{const m=String(t).replace(/```(?:json)?/g,'').match(/\{[\s\S]*\}/);if(!m)return null;try{return JSON.parse(m[0])}catch(e){return null}};
const hard=m=>Object.assign(new Error(m),{hard:1});
function aiErr(st,d){let m='';try{const j=typeof d=='string'?JSON.parse(d):d;m=j&&j.error&&(j.error.message||j.error)||''}catch(e){}
return st==401||st==403?'Chave inválida ou sem permissão.':st==402?'Sem crédito na conta da IA. Saldo negativo bloqueia até os modelos grátis.':st==429?'Limite de uso da IA (grátis: 20 por minuto e 50 por dia). Espere um pouco.':'Erro da IA ('+st+'). '+String(m).slice(0,120)}
const AIBAD={};
// tenta as chaves em ordem; se uma estourar o limite (429), ficar sem crédito (402) ou for inválida, passa para a próxima
async function aiCall(msgs,max,cfg){const a=cfg||aiGet(),ks=aiKeys(a);if(!ks.length||!a.url||!a.model)throw hard('Configure a IA primeiro.');
const now=Date.now(),order=ks.filter(k=>!(AIBAD[k]>now)).concat(ks.filter(k=>AIBAD[k]>now));let last;
for(const k of order){try{return await aiCall1(msgs,max,a,k)}catch(e){last=e;const st=e&&e.st;if(st==401||st==402||st==403||st==429){AIBAD[k]=Date.now()+(st==429?6e5:36e5);continue}throw e}}
throw last}
async function aiCall1(msgs,max,cfg,key){let a=cfg||aiGet();
a=Object.assign({},a,{model:String(a.model||'').split(',')[0].trim()});
const url=String(a.url).replace(/\/+$/,'')+'/chat/completions',body={model:a.model,messages:msgs,temperature:.2,max_tokens:max||3000};
if(/openrouter\.ai/.test(url)&&!/free/.test(a.model))body.reasoning={effort:'low'};
aiUsed();
const H={'Content-Type':'application/json',Authorization:'Bearer '+key,'X-Title':'Jejum e Dieta'},N=C().CapacitorHttp;let st,d;
try{
if(N&&N.request){const r=await N.request({url,method:'POST',headers:H,data:body,connectTimeout:15000,readTimeout:90000});st=r.status;d=r.data}
else{const c=new AbortController(),t=setTimeout(()=>c.abort(),90000);try{const r=await fetch(url,{method:'POST',headers:H,body:JSON.stringify(body),signal:c.signal});st=r.status;d=await r.text()}finally{clearTimeout(t)}}
}catch(e){throw hard('Sem conexão com a IA. Confira o endereço e a internet.')}
if((st==400||st==404)&&a.model=='openrouter/free')return aiCall1(msgs,max,Object.assign({},a,{model:'openrouter/free:free'}),key);
if(st>=400){const e=new Error(aiErr(st,d));e.hard=st==401||st==402||st==403||st==429;e.rate=st==429;e.st=st;throw e}
let j;try{j=typeof d=='string'?JSON.parse(d):d}catch(e){throw new Error('Resposta inesperada da IA.')}
const c=j&&j.choices&&j.choices[0]&&j.choices[0].message&&j.choices[0].message.content,t=Array.isArray(c)?c.map(x=>x.text||'').join(''):String(c||'');
if(!t.trim())throw new Error('A IA respondeu vazio. Tente outro modelo.');return t}
// tenta os modelos da lista em ordem (com 1 modelo, tenta 2 vezes). Erro de chave/crédito/conexão para na hora
async function aiJson(msgs,max,ok){const a=aiGet(),ms=String(a.model||'').split(',').map(x=>x.trim()).filter(Boolean);let err;
for(let t=0;t<Math.max(2,ms.length);t++){try{const j=jx(await aiCall(msgs,max,Object.assign({},a,{model:ms[t%ms.length]||''})));if(j&&ok(j))return j;err=new Error('A IA não devolveu dados válidos. Tente de novo.')}catch(e){if(e.hard&&!(e.rate&&ms.length>1))throw e;err=e}}throw err}
function aiRow(it){const p=it&&it.por100;if(!p||!it.nome)return null;
const n=k=>{const v=+p[AIM[k]];return v>0&&isFinite(v)?v:0},P=n('prot'),Cb=n('carb'),G=n('fat'),e=4*P+4*Cb+9*G;let kc=n('kcal');
if(!kc||(e>20&&Math.abs(kc-e)/e>.35))kc=e;if(!(kc>0))return null;
const x={};['sug','sat','trans','chol'].forEach(k=>{if(n(k)>0)x[k]=+n(k).toFixed(2)});
return{r:[String(it.nome).trim().slice(0,60)+' (IA)',Math.round(kc),r1(P),r1(Cb),r1(G),r1(n('fib')),Math.round(n('na')),Math.round(n('ca')),r1(n('fe')),Math.round(n('k')),r1(n('vC')),0,x,''],i:-1,src:'🤖',g:Math.round(+it.gramas)||0}}
async function aiFood(u){const img=await prep(u,{max:1100});
const P=aiHead()+'Foto de comida ou produto. Identifique o que aparece e estime em gramas a quantidade de cada item visível. Se for embalagem com tabela nutricional legível, use os valores dela. Senão use valores típicos por 100 g (TACO/USDA). Responda SÓ com JSON, sem texto extra: {"items":[{"nome":"nome em português","gramas":0,"confianca":0,"por100":'+AIS(14,0)+'}]}. No máximo 4 itens, o principal primeiro. Todos os valores são por 100 g do alimento. Campos terminados em _mg estão em mg.';
const j=await aiJson([{role:'user',content:[{type:'text',text:P},{type:'image_url',image_url:{url:img}}]}],3000,j=>(j.items||[]).some(x=>aiRow(x))),a=(j.items||[]).slice(0,4).map(aiRow).filter(Boolean);
if(!a.length)throw new Error('A IA não reconheceu comida na foto.');return a}
async function aiRun(){if(!aiOn())return aiCfg('food');if(!FS)return;toast('🤖 Analisando…');
try{const a=await aiFood(FS.u);FS.aiErr='';const w=$('#aie');if(w)w.remove();FS.pre=a.concat(FS.pre.filter(x=>x.src!='🤖'));foodFind(a[0].r[0].replace(/ \(IA\)$/,''))}
catch(e){FS.aiErr=String(e.message||e);fsShow(FS.q)}}
async function aiLabel(){if(!aiOn())return aiCfg('label');if(!LB)return;toast('🤖 Lendo o rótulo…');
try{const img=await prep(LB.s.u,{max:1600}),
P=aiHead()+'Esta foto mostra a tabela nutricional de um alimento (Brasil). Leia a tabela. Responda SÓ com JSON, sem texto extra: {"porcao_g":0,"por100":'+AIS(Object.keys(AIM).length,'null')+',"ingredientes":""}. Dê os valores POR 100 g (ou 100 ml). Se a tabela só tiver a coluna da porção, converta para 100 g usando o tamanho da porção. Use null no que não estiver na tabela. Não invente valores. Campos terminados em _mg estão em mg e os terminados em _ug em microgramas.',
j=await aiJson([{role:'user',content:[{type:'text',text:P},{type:'image_url',image_url:{url:img}}]}],3500,j=>j.por100&&Object.keys(j.por100).some(k=>j.por100[k]!=null&&isFinite(+j.por100[k])));
const v={};for(const k in AIM){const x=j.por100[AIM[k]];if(x!=null&&x!==''&&isFinite(+x))v[k]=+x}
if(!Object.keys(v).length)throw new Error('A IA não achou a tabela.');
const w=['Lido pela IA. Confira os valores com o rótulo.'];if(incons(v)>.35)w.push('As calorias não batem com os macros. Confira os valores.');
LB.o={v,por:+j.porcao_g||0,ing:String(j.ingredientes||'').slice(0,700),warn:w,raw:LB.o&&LB.o.raw,sc:Object.keys(v).length};labelForm('')}
catch(e){toast(String(e.message||e))}}
