const aiStat=()=>aiOn()?'✅ IA configurada · '+esc(aiGet().model)+' · hoje: '+aiUse()+' pedidos neste app (grátis: 50 por dia) · '+aiKeys(aiGet()).length+' chave'+(aiKeys(aiGet()).length>1?'s':''):'IA não configurada. Cole a chave e toque em Salvar.';
