function aiBody(){const a=aiGet();
return `<p style="font-size:13px;color:var(--m);margin-bottom:8px">Vale para o app todo: foto de comida e leitura de rótulo. Funciona com OpenRouter, OmniRoute ou qualquer serviço compatível com a API da OpenAI. A chave fica só neste aparelho e não entra no backup.</p>${aiFields('as',a)}<label class=row style="margin:10px 0 4px;font-size:14px"><input id=asa type=checkbox style="width:auto;margin:0" ${a.auto!==false?'checked':''}>Usar a IA automaticamente ao fotografar comida</label><small style="display:block;margin-bottom:10px">Desligue para economizar o limite grátis. Aí a IA só roda no botão 🤖.</small><label style="${AILB}">Como a IA deve se comportar (instruções)<textarea id=asp rows=7>${esc(a.prompt||AIP_DEF)}</textarea></label><small style="display:block;margin-bottom:8px">O formato da resposta (JSON) é fixo: o app adiciona sozinho. Aqui você muda o jeito de pensar: estilo, fontes, regras da sua dieta.</small><button style="margin-bottom:10px" onclick=aiPDef()>Restaurar o padrão</button><div class=two><button onclick="aiTest('as')">Testar conexão</button><button class=pri onclick="aiSave('as')">Salvar</button></div>${a.key?'<button style="width:100%;margin-top:8px" onclick="aiDel(\'as\')">Apagar a chave</button>':''}<p id=ais style="margin-top:10px;font-size:13px;color:var(--m)">${aiStat()}</p>`}
