const rowOf=(pid,rid)=>((S.wk.find(w=>w.id==pid)||{rows:[]}).rows.find(r=>r.id==rid))||{};
function glog(pid,rid){const d=day(dk());d.wl=d.wl||{};const p=d.wl[pid]=d.wl[pid]||{};let e=p[rid];if(!e||typeof e!='object'||!Array.isArray(e.s))e=p[rid]={s:[]};const n=nrm(rowOf(pid,rid)).ns||3;while(e.s.length<n)e.s.push({w:'',r:'',i:'',d:0});return e.s}
function lastLog(pid,rid){const d=dk(),ds=Object.keys(S.days).filter(x=>x<d).sort().reverse();for(const x of ds){const e=((S.days[x].wl||{})[pid]||{})[rid];if(e&&Array.isArray(e.s)&&e.s.some(s=>s.w!==''||s.r!==''))return e.s}return[]}
const e1rm=s=>Math.round(Math.max(0,...s.map(x=>(+x.w||0)*(1+(+x.r||0)/30))));
const sLog=(pid,rid,i,k,v)=>{glog(pid,rid)[i][k]=v;save()};
function sDone(pid,rid,i){const s=glog(pid,rid)[i],r=rowOf(pid,rid),la=lastLog(pid,rid)[i]||{};s.d=s.d?0:1;if(s.d){if(s.w==='')s.w=la.w!=null&&la.w!==''?la.w:(r.w||'');if(s.r==='')s.r=la.r!=null&&la.r!==''?la.r:String(r.rp||'').split('-').pop();if(s.i==='')s.i=la.i!=null?la.i:(r.rir??'');rest(r.rs||S.rd)}save();render()}
const pf=(r,k,l)=>`<label style="flex:1;min-width:58px;font-size:11px;color:var(--m)">${l}<input value="${esc(r[k]??'')}" style="margin:0;padding:6px" onchange="wkSet(${r.id},'${k}',this.value)"></label>`;
const wkSet=(rid,k,v)=>{const r=cur().rows.find(x=>x.id==rid);r[k]=['m','sp','inc','ns','rs','i'].includes(k)?(+v||0):v;save();render()};
