const head=`<div class="row sp" onclick="tgO(${r.id})"><div style="flex:1"><b>${esc(r.n)}</b><br><small>${r.m||0} min${r.sp?' · '+r.sp+' km/h':''}${r.inc?' · '+r.inc+'%':''}${sp?'':' · '+esc(o[0])}</small></div><b>${k} kcal ${open?'▾':'▸'}</b></div>`;
