function vWk(){const w=cur();if(!w)return'';let kc=0;const rows=w.rows.map(r=>{nrm(r);if(r.k=='c'){kc+=kcC(r);return cCard(r)}return sCard(r,w)}).join(''),hasF=w.rows.some(r=>r.k=='f'),sk=hasF?Math.round(kpm(SMET[w.si||1][1])*(w.dm||0)):0;
return rbar()+`<div class="row sp" style="margin:10px 0"><button onclick="go('treino')">‹ Treino</button><button onclick="wkRm()" style="color:var(--r)">Apagar</button></div><input value="${esc(w.t)}" onchange="cur().t=clean(this.value)||cur().t;save()" style="font-weight:600;font-size:17px">`+(rows||'<p style="padding:14px 0"><small>Toque em + Exercício ou + Cardio.</small></p>')+`<div class=row style="margin:10px 0"><button style="flex:1" onclick="exPick('f')">+ Exercício</button><button style="flex:1" onclick="exPick('c')">+ Cardio</button></div>`+(hasF?`<div class=card><h2>Musculação</h2><div class=row><input type=number value="${w.dm||0}" onchange="cur().dm=+this.value;save();render()" style="margin:0;width:80px"><small>min</small>${SMET.map((s,i)=>`<button class="${(w.si||1)==i?'pri':''}" onclick="cur().si=${i};save();render()">${s[0]}</button>`).join('')}</div></div>`:'')+`<div class=card><div class="row sp"><span>Total estimado</span><b>${kc+sk} kcal</b></div></div><button class=pri style="width:100%" onclick=wkDone()>Concluir treino</button>`}
function wkDone(){const w=cur(),d=day(dk());if((d.wd||{})[w.id]&&!confirm('Já concluído hoje. Registrar de novo?'))return;let n=0;d.exl=d.exl||[];w.rows.filter(r=>r.k=='c'&&r.m>0).forEach(r=>{const L=lv(r.n),o=L[r.i||0]||L[0];d.exl.push({id:Date.now()+n++,n:r.n+' · '+(SPD(r.n)&&r.sp>0?r.sp+' km/h'+(r.inc?' · '+r.inc+'%':''):o[0]),m:r.m,k:kcC(r)})});if(w.rows.some(r=>r.k=='f')&&w.dm>0)d.exl.push({id:Date.now()+n++,n:'Musculação · '+w.t,m:w.dm,k:Math.round(kpm(SMET[w.si||1][1])*w.dm)});d.wd=d.wd||{};d.wd[w.id]=1;save();toast('Treino concluído!');go('treino')}
function exAdd(n){const w=cur();if(!w)return;const e=EXI.find(x=>x[0]==n);w.rows.push(EK=='c'?{id:++RID,k:'c',n,i:e?e[2]:0,m:10,sp:0,inc:0}:{id:++RID,k:'f',n,ns:3,rp:'12',w:'',rir:'',rs:0});save();closeS();render()}
