const ncCard=()=>{const l=day().food.filter(x=>x.meal==NC),T=l.reduce((a,x)=>a.map((n,i)=>n+(x.v[i]||0)),[0,0,0,0]);return `<div class="card ml" style="border:1px dashed var(--ln);box-shadow:none;background:transparent"><div class=mh><div><b>🍪 Sem contar</b><small>Comidas de vez em quando. Não entram na meta.</small></div><span class=k>${l.length?Math.round(T[0])+' kcal':''}</span></div>${l.map(y=>itemRow(y,NC)).join('')}${l.length?`<div class=mi style="background:var(--bg3)"><div class=n><b>Total sem contar</b><br><small>P ${r1(T[1])} · C ${r1(T[2])} · G ${r1(T[3])}</small></div><span class=k>${Math.round(T[0])} kcal</span></div>`:''}<button class=ma onclick="fSheet('${NC}')">${IC.plus} Adicionar</button></div>`};
const NGP=[['Carboidratos',['carb','fib','sug']],['Lipídios',['fat','sat','trans','chol']],['Proteína',['prot']],['Vitaminas',['vA','vC','vD','vE','vK','vB12','fol']],['Minerais',['na','ca','fe','k','mg','zn','p']]],LIM=['na','sat','trans','chol','sug'];
const nutCard=()=>{const o=nutDay(D),tg=k=>k=='carb'?S.g.c:k=='prot'?S.g.p:k=='fat'?S.g.f:(NUT.find(n=>n[0]==k)||[])[3]||0,
row=k=>{const n=NUT.find(z=>z[0]==k),v=o[k]||0,t=tg(k),over=LIM.includes(k)&&t>0&&v>t;return `<div class=nb><div class=l><span>${n[1].trim()}</span><span>${fmtN(v,n[2])}${t?' / '+t+' '+n[2]:''}</span></div>${t?`<div class="bar thin"><i style="width:${pct(v,t)}%;--col:${over?'var(--r)':v>=t&&!LIM.includes(k)?'var(--g)':'var(--br)'}"></i></div>`:''}</div>`};
return `<details class=card><summary>Nutrição do dia</summary>${NGP.map(g=>`<div class=ng>${g[0]}</div>${g[1].map(row).join('')}`).join('')}<details style="margin-top:16px"><summary style="color:var(--br);font-weight:600">Ver como rótulo</summary><div style="margin-top:10px">${nlabel(o,'Total do dia')}</div></details></details>`};
