const nutDay=d=>{const a=S.days[d]||{},o={};(a.food||[]).forEach(e=>{if(e.meal==NC)return;const f=full(e);for(const k in f)o[k]=(o[k]||0)+f[k]});(a.adj||[]).forEach(z=>['kcal','prot','carb','fat'].forEach((k,i)=>o[k]=(o[k]||0)+z.v[i]));const nx=a.nx||{};for(const k in nx)o[k]=(o[k]||0)+nx[k];return o};
function vMicro(){const days=isWk()?wkDays(D):[D],o=nxSum(days),m=pmul(),cv=nxCov(days),hide=S.mcHide;
const row=n=>{const v=nxV(o,n),t=tgt(n[0])*m,lim=!!n[5];if(hide&&!(v>0))return'';const p=t?v/t*100:0,over=lim&&t>0&&v>t,col=over?'var(--r)':(!lim&&t>0&&v>=t)?'var(--g)':'var(--br)';
return `<div class=nb onclick="mcSheet('${n[0]}')" style="cursor:pointer"><div class=l><span>${n[1]}${S.tg&&S.tg[n[0]]!=null?' ✎':''}</span><span>${fv(v,n[2])}${t?' / '+fv(t,n[2]):''} ${n[2]}${t?' · '+Math.round(p)+'%':''}</span></div>${t?`<div class="bar thin"><i style="width:${Math.min(100,p)}%;--col:${col}"></i></div>`:''}</div>`};
return dnav()+`<h1 style="margin-top:4px">Micronutrientes</h1>${perSeg()}${isWk()?`<small style="display:block;margin:-4px 4px 10px">Semana ${lbl(days[0])} – ${lbl(days[6])} · metas × 7</small>`:''}${cv[0]>cv[1]?`<div class=wr>${cv[0]-cv[1]} de ${cv[0]} alimentos não trazem dados de micronutrientes, então os totais podem estar baixos. Abra o alimento e toque em “Completar micronutrientes”, ou use alimentos da internet (USDA).</div>`:''}`+NXG.map((g,gi)=>{const l=NX.filter(n=>n[4]==gi).map(row).join('');return l?`<div class=card><h2>${g}</h2>${l}</div>`:''}).join('')+`<div class=two style="margin-top:6px"><button onclick="S.mcHide=!S.mcHide;save();render()">${hide?'Mostrar todos':'Ocultar zerados'}</button><button onclick="mcReset()">Metas padrão</button></div><small style="display:block;margin:10px 4px">Toque em um nutriente para ver as fontes, mudar a meta ou somar um suplemento.</small>`}
