function mcSheet(k){const n=nxN(k);if(!n)return;const o=nutDay(D),v=nxV(o,n),man=(day().nx||{})[k]||0,t=tgt(k),mine=S.tg&&S.tg[k]!=null;
sheet(`<h2>${n[1]}</h2><div class=mk style="grid-template-columns:repeat(2,1fr)"><div><b>${fv(v,n[2])} ${n[2]}</b><small>no dia ${lbl(D)}</small></div><div><b>${t?fv(t,n[2])+' '+n[2]:'sem meta'}</b><small>meta${mine?' (sua)':''}${n[5]?' · limite':''}</small></div></div><label style="display:block;font-size:13px;color:var(--m);margin:8px 0">Minha meta por dia (${n[2]})<input id=mct type=number step=any value="${mine?S.tg[k]:''}" placeholder="${defT(k)||'sem meta'}"></label><div class=two style="margin-bottom:6px"><button class=pri onclick="mcSave('${k}')">Salvar meta</button><button onclick="mcSave('${k}',1)">Padrão</button></div>${n[6]?'':`<h2 style="margin-top:18px">Somar no dia</h2><small style="display:block;margin-bottom:8px">Para suplementos ou algo que não está nos alimentos. ${man?'Já somado: '+fv(man,n[2])+' '+n[2]+'.':''}</small><div class=row><input id=mca type=number step=any placeholder="quantidade em ${n[2]}" style="margin:0"><button onclick="mcAdd('${k}')">+ Somar</button>${man?`<button onclick="mcAdd('${k}',1)">Zerar</button>`:''}</div>`}${mcTop(k,n[2])}`)}
function mcSave(k,reset){const e=$('#mct'),v=e?e.value:'',mp={carb:'c',fat:'f',prot:'p'};S.tg=S.tg||{};if(mp[k]){if(!reset&&v!=='')S.g[mp[k]]=+v;delete S.tg[k]}else if(reset||v==='')delete S.tg[k];else S.tg[k]=+v;save();closeS();render()}
function mcAdd(k,clear){const a=day();a.nx=a.nx||{};if(clear)delete a.nx[k];else{const v=+$('#mca').value;if(!(v>0))return toast('Informe a quantidade.');a.nx[k]=(a.nx[k]||0)+v}save();render();mcSheet(k)}
