function vFichas(){const l=FI().slice().reverse();return `<h1>Treino</h1>${tseg('fichas')}<button class=pri style="width:100%;margin-bottom:6px" onclick=fxStart()>📥 Digitalizar treino</button><small style="display:block;margin:0 4px 12px">Fotografe ou importe a ficha (imagem ou PDF). O app lê os exercícios e guarda aqui.</small>${l.length?l.map(f=>{const n=f.days.reduce((s,d)=>s+d.ex.length,0);return `<div class="card lst"><button class=li onclick="fxOpen(${f.id})"><span class=ic>🗂️</span><span class=t>${esc(f.t)}<small>${f.days.length} dia${f.days.length==1?'':'s'} · ${n} exercício${n==1?'':'s'} · ${lbl(f.date)}</small></span><span class=bd>${f.src=='ia'?'IA':'OCR'}</span><span class=ch>›</span></button></div>`}).join(''):'<div class=card style="text-align:center"><small>Nenhuma ficha ainda.</small></div>'}`}
