async function fxAI(imgs){const ims=await Promise.all(imgs.slice(0,4).map(u=>prep(u,{max:1600})));
const P=aiHead()+'As imagens mostram uma ficha de treino (academia). Digitalize: separe por dia/treino (A, B, C… ou segunda, terça…) e liste cada exercício com séries, repetições, carga e descanso. Responda SÓ com JSON, sem texto extra: {"titulo":"","dias":[{"nome":"","exercicios":[{"nome":"","series":0,"reps":"","carga_kg":null,"descanso_s":null,"obs":""}]}]}. Copie os nomes como estão escritos. Use null no que não estiver na ficha. reps pode ser "12", "8-12" ou "até a falha". Não invente exercícios.';
const j=await aiJson([{role:'user',content:[{type:'text',text:P}].concat(ims.map(u=>({type:'image_url',image_url:{url:u}})))}],4000,j=>Array.isArray(j.dias)&&j.dias.some(d=>Array.isArray(d.exercicios)&&d.exercicios.length));
return{t:String(j.titulo||'Ficha de treino').slice(0,60),days:j.dias.map((d,i)=>({n:String(d.nome||'Treino '+(i+1)).slice(0,40),ex:(d.exercicios||[]).filter(x=>x&&x.nome).map(x=>({n:String(x.nome).slice(0,60),s:+x.series||0,r:String(x.reps==null?'':x.reps).slice(0,12),kg:+x.carga_kg>0?+x.carga_kg:0,rs:+x.descanso_s>0?Math.round(+x.descanso_s):0,ob:String(x.obs||'').slice(0,80)}))})).filter(d=>d.ex.length)}}
async function fxOCR(imgs){let rows=[];for(const u of imgs){let r=await ocrRead(u,0),rr=rowsOf(r);if(rr.length<4){r=await ocrRead(await prep(u,{max:2000,enh:1}),0);rr=rowsOf(r)}rows=rows.concat(rr)}return fxParse(rows)}
// leitura sem IA: acha "séries x reps", carga e descanso em cada linha
const FXDAY=/^(treino|dia|ficha|segunda|ter[cç]a|quarta|quinta|sexta|s[aá]bado|domingo|seg|ter|qua|qui|sex|s[aá]b|dom)\b/;
function fxParse(rows){const days=[];let cur=null,title='';const nd=n=>{cur={n:(n||'Treino '+(days.length+1)).slice(0,40),ex:[]};days.push(cur)};
rows.forEach(r=>{const t=r.t.replace(/\s+/g,' ').trim();if(t.length<3)return;const n=nz(t),
sr=t.match(/(\d{1,2})\s*[x×*]\s*(\d{1,3}(?:\s*[-–/]\s*\d{1,3})?)/i)||t.match(/(\d{1,2})\s*s[eé]ries?\s*(?:de|x)?\s*(\d{1,3}(?:\s*[-–]\s*\d{1,3})?)/i),
kgm=t.match(/(\d{1,3}(?:[.,]\d+)?)\s*(kg|quilos?|lbs?)\b/i),rsm=t.match(/(?:desc(?:anso)?|int(?:ervalo)?|rest)\.?\s*:?\s*(\d{1,3})\s*(min|m\b|s\b|seg|segundos|'|")?/i);
if(!sr){const hdr=FXDAY.test(n)||/^(treino|ficha)\s*[a-f0-9]/.test(n)||/^[a-f]\s*[-–:)]/.test(n)||(/^[^\d]{4,40}$/.test(t)&&t===t.toUpperCase()&&/[A-ZÀ-Ú]{3}/.test(t));
if(hdr){nd(t.replace(/[:\-–]+$/,'').trim());return}
if(!cur&&!title&&/[a-zà-ú]{4}/i.test(t)&&!/\d/.test(t))title=t.slice(0,60);
const cm=t.match(/(\d{1,3})\s*(?:min|minutos)\b/i);
if(cm&&/(esteira|bike|bicicleta|corrida|caminhada|cardio|eliptico|escada|remo|aquecimento)/.test(n)){if(!cur)nd();cur.ex.push({n:t.replace(/\d{1,3}\s*(?:min|minutos)\b/i,'').replace(/[-–:]+\s*$/,'').trim()||'Cardio',s:0,r:cm[1]+' min',kg:0,rs:0,ob:''})}
return}
if(!cur)nd();
let name=t.slice(0,sr.index).trim();if(name.length<3)name=t.slice(sr.index+sr[0].length).replace(kgm?kgm[0]:'','').trim();
name=name.replace(/^\d+[.)\-–]\s*/,'').replace(/^[-•*·]\s*/,'').replace(/[-–:(]+\s*$/,'').trim();if(name.length<2)return;
let rs=0;if(rsm){rs=+rsm[1];const u=rsm[2]||'';if(/^m/i.test(u))rs*=60;else if(!u&&rs<=5)rs*=60}
let kg=0;if(kgm){kg=+kgm[1].replace(',','.');if(/^lb/i.test(kgm[2]))kg=+(kg*.4536).toFixed(1)}
cur.ex.push({n:name.slice(0,60),s:+sr[1],r:sr[2].replace(/\s+/g,'').replace(/[–/]/,'-'),kg,rs,ob:''})});
return{t:title||'Ficha de treino',days:days.filter(x=>x.ex.length)}}
function fxReview(){const d=FX.d,fld=(l,i,j,k,v,ty)=>`<label style="flex:1;min-width:0;font-size:11px;color:var(--m)">${l}<input ${ty||'type=number'} step=any value="${v||''}" oninput="FX.d.days[${i}].ex[${j}].${k}=${ty?'this.value':'+this.value||0'}" style="margin:2px 0 0;padding:8px"></label>`,
dayH=(x,i)=>`<div class=card style="padding:12px"><div class=row style="margin-bottom:6px"><input value="${esc(x.n)}" oninput="FX.d.days[${i}].n=this.value" style="margin:0;font-weight:650"><button class=ghost onclick="fxDay(${i})">🗑</button></div>${x.ex.map((e,j)=>`<div style="padding:10px 0;border-top:1px solid var(--ln)"><div class=row><input value="${esc(e.n)}" oninput="FX.d.days[${i}].ex[${j}].n=this.value" style="margin:0"><button class=ghost onclick="fxEx(${i},${j})">✕</button></div><div class=row style="margin-top:6px">${fld('Séries',i,j,'s',e.s)}${fld('Reps',i,j,'r',e.r,'type=text')}${fld('Carga kg',i,j,'kg',e.kg)}${fld('Desc. s',i,j,'rs',e.rs)}</div></div>`).join('')}<button style="width:100%;margin-top:8px" onclick="fxEx(${i},-1)">+ Exercício</button></div>`;
sheet(`<h2>Ficha digitalizada</h2><span class=bd>${FX.src=='ia'?'LIDA PELA IA':'LIDA NO APARELHO'}</span>${FX.warn?`<div class=wr>${esc(FX.warn)}</div>`:''}<input value="${esc(d.t)}" oninput="FX.d.t=this.value" placeholder="Nome da ficha" style="font-weight:650;margin:8px 0">${d.days.map(dayH).join('')}<div class=two style="margin-top:8px"><button onclick="fxDay(-1)">+ Dia</button>${FX.edit?'':'<button onclick="fxPickSheet()">Outras páginas</button>'}</div><button class=pri style="width:100%;margin-top:12px;padding:14px" onclick=fxSave()>${FX.edit?'Salvar alterações':'Salvar na aba Fichas'}</button>`)}
function fxEx(i,j){const x=FX.d.days[i];if(j<0)x.ex.push({n:'',s:3,r:'10',kg:0,rs:0,ob:''});else x.ex.splice(j,1);fxReview()}
function fxDay(i){if(i<0)FX.d.days.push({n:'Treino '+(FX.d.days.length+1),ex:[]});else FX.d.days.splice(i,1);fxReview()}
async function fxSave(){const d=FX.d;d.days=d.days.map(x=>({n:(x.n||'Treino').trim()||'Treino',ex:x.ex.filter(e=>(e.n||'').trim())})).filter(x=>x.ex.length);if(!d.days.length)return toast('Adicione pelo menos um exercício.');
const t=(d.t||'').trim()||'Ficha de treino';
if(FX.edit){const f=FI().find(z=>z.id==FX.edit);if(f){f.t=t;f.days=d.days}save();closeS();render();return toast('Ficha atualizada')}
const id=Date.now(),ids=[];for(let i=0;i<FX.imgs.length;i++){try{const u=await prep(FX.imgs[i],{max:1400});await ph('put','f'+id+'_'+i,u);ids.push('f'+id+'_'+i)}catch(e){}}
FI().push({id,t,src:FX.src,date:dk(),days:d.days,img:ids});save();closeS();go('fichas');toast('Ficha salva em Fichas')}
function fxOpen(id){const f=FI().find(x=>x.id==id);if(!f)return;
sheet(`<h2>${esc(f.t)}</h2><small>${lbl(f.date)} · ${f.src=='ia'?'lida pela IA':'lida no aparelho'}</small>${f.days.map(d=>`<div class="card ml" style="margin:10px 0 0"><div class=mh><b>${esc(d.n)}</b></div>${d.ex.map(e=>`<div class=mi><div class=n><div>${esc(e.n)}</div><small>${[e.s&&e.r?e.s+' × '+e.r:e.r,e.kg?e.kg+' kg':'',e.rs?e.rs+' s desc.':'',e.ob].filter(Boolean).join(' · ')}</small></div></div>`).join('')}</div>`).join('')}<button class=pri style="width:100%;margin-top:12px" onclick="fxMk(${id})">▶ Criar treino(s) para treinar</button><div class=two style="margin-top:8px"><button onclick="fxImg(${id})">🖼️ Original</button><button onclick="fxEd(${id})">✏️ Editar</button><button onclick="fxDel(${id})">🗑 Excluir</button></div>`)}
function fxEd(id){const f=FI().find(x=>x.id==id);if(!f)return;FX={d:JSON.parse(JSON.stringify({t:f.t,days:f.days})),imgs:[],src:f.src,edit:id,warn:''};fxReview()}
async function fxImg(id){const f=FI().find(x=>x.id==id);if(!f)return;const us=[];for(const k of f.img||[]){try{const u=await ph('get',k);if(u)us.push(u)}catch(e){}}
sheet(`<h2>Original</h2>${us.length?us.map(u=>`<img src="${u}" style="width:100%;border-radius:12px;margin-bottom:10px">`).join(''):'<small>Sem imagem guardada.</small>'}<button style="width:100%" onclick="fxOpen(${id})">Voltar</button>`)}
function fxDel(id){if(!confirm('Excluir esta ficha?'))return;S.fichas=FI().filter(x=>x.id!=id);save();closeS();render()}
function fxMk(id){const f=FI().find(x=>x.id==id);if(!f)return;S.wk=S.wk||[];let n=0;
f.days.forEach((d,i)=>{S.wk.push({id:Date.now()+i,t:f.days.length>1?f.t+' · '+d.n:f.t,rows:d.ex.map((e,j)=>({id:Date.now()+i*100+j+1,k:'f',n:e.n,sr:(e.s||3)+'x'+((String(e.r).match(/\d+(?:-\d+)?/)||['10'])[0]),rs:e.rs||0,w0:e.kg||0})),dm:45,si:1});n++});
save();closeS();toast(n+' treino'+(n>1?'s':'')+' criado'+(n>1?'s':'')+' em Treinar');go('treino')}
// ---- água: recipientes (copo, garrafa 500 ml…), registro do dia e progresso
const WC0=[{n:'Copo',ml:250},{n:'Garrafa',ml:500},{n:'Garrafa grande',ml:1000}];
const wcs=()=>{if(!Array.isArray(S.wc)||!S.wc.length)S.wc=WC0.map(x=>Object.assign({},x));return S.wc};
const wat=(n,nm,c)=>{const a=day(D);a.wl=a.wl||[];n=+n||0;
if(n>0)a.wl.push(Object.assign({t:Date.now(),ml:n,n:nm||n+' ml'},c?{c:1}:{}));
else if(n<0){let r=-n;while(r>0&&a.wl.length){const l=a.wl[a.wl.length-1];if(l.ml<=r){r-=l.ml;a.wl.pop()}else{l.ml-=r;r=0}}}
a.water=Math.max(0,(a.water||0)+n);save();render()};
const wTxt=a=>{const c={};(a.wl||[]).forEach(x=>{if(x.c)c[x.n]=(c[x.n]||0)+1});return Object.keys(c).map(k=>c[k]+'× '+k).join(' · ')};
function wAdd(i){const c=wcs()[i];if(!c)return;wat(c.ml,c.n,1);toast('💧 +1 '+c.n+' ('+c.ml+' ml) · '+day(D).water+' de '+S.g.water+' ml')}
function wCustom(){const v=+$('#wcv').value;if(!(v>0))return toast('Informe os ml.');wat(v,v+' ml');toast('💧 +'+v+' ml · '+day(D).water+' de '+S.g.water+' ml')}
function wDel(i){const a=day(D),l=(a.wl||[])[i];if(!l)return;a.wl.splice(i,1);a.water=Math.max(0,(a.water||0)-l.ml);save();render()}
function wGoal(){sheet(`<h2>Meta de água por dia</h2><label style="display:block;font-size:13px;color:var(--m)">ml por dia<input id=wg type=number inputmode=numeric value="${S.g.water}"></label><button class=pri style="width:100%;margin-top:12px" onclick="S.g.water=+$('#wg').value||2500;save();closeS();render()">Salvar</button>`)}
function wcNew(){wcs().push({n:'Recipiente',ml:300});OPN.wc=1;save();render()}
function wcDel(i){if(wcs().length<2)return toast('Mantenha pelo menos um recipiente.');wcs().splice(i,1);save();render()}
function vAgua(){const a=day(D),g=S.g.water||2500,w=a.water||0,wl=a.wl||[],extra=w-wl.reduce((s,x)=>s+x.ml,0),rest=g-w,sm=wTxt(a);
return dnav()+`<h1 style="margin-top:4px">Água</h1><div class=card><div class=hh><h2>${lbl(D)}</h2><button class=lk onclick=wGoal()>Meta ${g} ml</button></div><div style="font-size:34px;font-weight:700;letter-spacing:-.02em">${w} <small style="font-size:16px;font-weight:500">ml de ${g} ml</small></div><div style="margin:2px 0 12px;font-weight:500">${sm||'<small>Toque em um recipiente abaixo.</small>'}</div><div class=bar style="height:14px"><i style="width:${pct(w,g)}%;--col:#38bdf8"></i></div><small style="display:block;margin-top:8px">${rest>0?'Faltam '+rest+' ml':'Meta batida! +'+(-rest)+' ml'}</small></div>`+
`<div class=card><h2>Adicionar</h2><div class=wgrid>${wcs().map((c,i)=>`<button class=wb onclick="wAdd(${i})"><span>💧</span><b>${esc(c.n)}</b><small>${c.ml} ml</small></button>`).join('')}</div><div class=row style="margin-top:12px"><input id=wcv type=number inputmode=numeric placeholder="Outro valor em ml" style="margin:0"><button class=pri onclick=wCustom()>+ Adicionar</button></div></div>`+
`<details class=card ${OPN.wc?'open':''} ontoggle="OPN.wc=this.open"><summary>Meus recipientes</summary>${wcs().map((c,i)=>`<div class=row style="margin-top:10px"><input value="${esc(c.n)}" onchange="wcs()[${i}].n=this.value;save();render()" placeholder="Nome (ex.: Garrafa)" style="margin:0"><input type=number inputmode=numeric value="${c.ml}" onchange="wcs()[${i}].ml=+this.value||0;save();render()" style="margin:0;width:96px"><button class=ghost onclick="wcDel(${i})">🗑</button></div>`).join('')}<button style="width:100%;margin-top:10px" onclick=wcNew()>+ Novo recipiente</button><small style="display:block;margin-top:8px">Ex.: Garrafa 500 ml. Tocar no recipiente soma na água do dia.</small></details>`+
`<div class=card><h2>Registro</h2>${wl.length?wl.map((x,i)=>`<div class="row sp" style="padding:8px 0;${i?'border-top:1px solid var(--ln)':''}"><span>${new Date(x.t).toLocaleTimeString(LC(),{hour:'2-digit',minute:'2-digit'})} · ${esc(x.n)}</span><span class=row><b>${x.ml} ml</b><button class=ghost onclick="wDel(${i})">✕</button></span></div>`).join(''):'<small>Nada registrado ainda.</small>'}${extra>0?`<div class="row sp" style="padding:8px 0;border-top:1px solid var(--ln)"><span>Outros registros</span><b>${extra} ml</b></div>`:''}</div>`}
